def construct():
    P = 1009
    M = 5
    
    # Pre-compute quadratic residues and their smallest positive root
    # root_map[r] will hold the smallest x in [1, P-1] such that x^2 % P == r
    # is_qr[r] will be True if r is a quadratic residue
    root_map = [0] * P
    is_qr = [False] * P
    
    # Iterate x from 1 to P-1
    # Note: (P-x)^2 % P == x^2 % P, so we only need to iterate up to P//2 
    # to find all unique residues, but we need the smallest root.
    # Since x and P-x give the same residue, and x < P-x for x < P/2,
    # the smallest root for a residue generated by x (where x <= P//2) is x.
    # If a residue is generated by x > P//2, its smallest root is P-x < P//2.
    # So iterating x from 1 to P//2 is sufficient to populate root_map with smallest roots.
    half_p = P // 2
    for x in range(1, half_p + 1):
        r = (x * x) % P
        if not is_qr[r]:
            is_qr[r] = True
            root_map[r] = x
    
    # Construct a bitmask where bit i is set if i is a quadratic residue
    # We use an integer for the bitmask. P=1009 fits easily in a Python int.
    mask = 0
    for r in range(1, P):
        if is_qr[r]:
            mask |= (1 << r)
            
    # Search for the minimum start s in [1, P-M]
    # We need s, s+1, ..., s+M-1 to all be quadratic residues.
    # This corresponds to (M) consecutive bits set in the mask starting at bit s.
    # The pattern of M ones is (1 << M) - 1.
    target_pattern = (1 << M) - 1
    
    # Max s is P - M because s+M-1 <= P-1 (since residues 1..P-1 are valid, 0 is excluded)
    # Actually, the problem states 1 <= ri <= 1008.
    # The residues are s, s+1, ..., s+4.
    # If s+4 > 1008, i.e., s > 1004, we would hit 1009 (which is 0 mod 1009) or wrap.
    # The problem excludes zero residues and wraparound.
    # So s+4 <= 1008 => s <= 1004.
    # P - M = 1009 - 5 = 1004. So the range is correct.
    
    for s in range(1, P - M + 1):
        # Check if bits s through s+M-1 are all set
        if (mask >> s) & target_pattern == target_pattern:
            # Found the minimal s
            roots = [root_map[s + i] for i in range(M)]
            return {'start': s, 'roots': roots}
            
    # Fallback (should not happen for P=1009, M=5 as there are many QRs)
    # If no 5 consecutive QRs found, return a dummy valid structure or raise error.
    # Given the density of QRs (~1/2), 5 consecutive is rare but exists.
    # The seed program returned s=1004, so it exists.
    return {'start': 1, 'roots': [1, 1, 1, 1, 1]}
